CREATE TABLE IF NOT EXISTS store_users (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(180) NOT NULL,description VARCHAR(2000),category VARCHAR(100) NOT NULL DEFAULT 'سایر',price_toman BIGINT NOT NULL DEFAULT 0,stock INTEGER NULL,image_url VARCHAR(500),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS store_orders (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES store_users(id),customer_name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,address VARCHAR(1200) NOT NULL,note VARCHAR(500),total_toman BIGINT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES store_orders(id),product_id BIGINT NOT NULL REFERENCES products(id),product_name VARCHAR(180) NOT NULL,image_url VARCHAR(500),unit_price_toman BIGINT NOT NULL,quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages (
id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(180) NOT NULL,subject VARCHAR(150),message VARCHAR(3000) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_active ON products(active);
CREATE INDEX IF NOT EXISTS idx_orders_user ON store_orders(user_id);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);